        <div class="atlas-image-dialog-card">
            <div class="aid-header">
                <div class="aid-header-title">
                    <i class="fa fa-picture-o aid-header-icon" aria-hidden="true"></i>
                    <h3 id="aid-title">Insert Image</h3>
                </div>
                <button type="button" class="aid-close-btn" id="aid-btn-close" title="Close (Esc)">
                    <i class="fa fa-times" aria-hidden="true"></i>
                </button>
            </div>

            <!-- Tabs -->
            <div class="aid-tabs">
                <button type="button" class="aid-tab active" id="aid-tab-upload">
                    <i class="fa fa-upload"></i> Upload from PC
                </button>
                <button type="button" class="aid-tab" id="aid-tab-url">
                    <i class="fa fa-globe"></i> From Web / URL
                </button>
            </div>

            <div class="aid-body">
                <!-- Tab 1: Upload from PC -->
                <div class="aid-panel active" id="aid-panel-upload">
                    <input type="file" id="aid-file-input" accept="image/*" style="display: none;" />
                    
                    <div class="aid-dropzone" id="aid-dropzone">
                        <i class="fa fa-cloud-upload aid-dropzone-icon"></i>
                        <p class="aid-dropzone-text"><strong>Click to browse</strong> or drag and drop image here</p>
                        <span class="aid-dropzone-sub">PNG, JPG, GIF, WebP, SVG</span>
                    </div>

                    <div class="aid-preview-box" id="aid-preview-box" style="display: none;">
                        <img id="aid-preview-img" src="" alt="Preview" class="aid-preview-img" />
                        <div class="aid-preview-meta">
                            <span id="aid-preview-name" class="aid-preview-name">image.png</span>
                            <span id="aid-preview-size" class="aid-preview-size">0 KB</span>
                            <button type="button" id="aid-preview-remove" class="aid-preview-remove-btn" title="Choose another image">Change</button>
                        </div>
                    </div>
                </div>

                <!-- Tab 2: URL -->
                <div class="aid-panel" id="aid-panel-url" style="display: none;">
                    <div class="aid-field">
                        <label for="aid-input-url">Image URL</label>
                        <input type="url" id="aid-input-url" class="aid-input" placeholder="https://example.com/image.png" />
                    </div>
                </div>

                <!-- Common Metadata Fields -->
                <div class="aid-fields-common">
                    <div class="aid-field">
                        <label for="aid-input-alt">Description / Alt Text</label>
                        <input type="text" id="aid-input-alt" class="aid-input" placeholder="Brief description of the image..." />
                    </div>
                    <div class="aid-field aid-field-width">
                        <label for="aid-input-width">Width (optional)</label>
                        <input type="text" id="aid-input-width" class="aid-input" placeholder="e.g. 400 or 100%" />
                    </div>
                </div>
            </div>

            <div class="aid-footer">
                <button type="button" class="aid-btn aid-btn-cancel" id="aid-btn-cancel">Cancel</button>
                <button type="button" class="aid-btn aid-btn-primary" id="aid-btn-insert">
                    <i class="fa fa-check"></i> Insert Image
                </button>
            </div>
        </div>
