        '    body { font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: var(--bg-primary); color: var(--text-primary); line-height: 1.7; min-height: 100vh; position: relative; overflow-x: hidden; }',
        '    .nav-header { position: sticky; top: 16px; z-index: 100; max-width: 1000px; margin: 16px auto 48px auto; padding: 12px 24px; background: var(--bg-pill); backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px); border: 1px solid var(--border); border-radius: 9999px; display: flex; align-items: center; justify-content: space-between; gap: 16px; box-shadow: var(--shadow); }',
        '    .nav-left { display: flex; align-items: center; gap: 14px; }',
