        '    .article-container { max-width: 900px; margin: 0 auto; padding: 0 24px 80px 24px; position: relative; z-index: 1; }',
        '    .article-header { margin-bottom: 32px; background: var(--bg-card); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 40px 32px; box-shadow: var(--shadow); }',
        '    .article-title { font-size: 2.4rem; font-weight: 800; line-height: 1.25; margin-bottom: 16px; letter-spacing: -0.02em; color: var(--text-primary); }',
